Use Convex 1.44.0. Users have a by_age index on ["age"]. Ages are finite numbers, and the number of distinct values fits query limits. The loop must return sorted distinct ages while skipping duplicate runs through the index. The progress guard stops a mistaken seek from looping forever.

```ts
import { query } from "./_generated/server";
import { v } from "convex/values";
import { paginationOptsValidator, paginationResultValidator } from "convex/server";
export const candidate = query({
  args: {},
  handler: async ctx => {
    const ages: number[] = [];
    let row = await ctx.db.query("users").withIndex("by_age").first();
    while (row !== null) {
      const previousAge = row.age;
      ages.push(previousAge);
      row = await (/* OPTION */);
      if (row !== null && row.age <= previousAge) throw new Error("No progress");
    }
    return ages;
  },
});
```
